function toE164PL(raw){let d=String(raw||'').replace(/[^\d+]/g,'');if(d.startsWith('+48'))d=d.slice(3);else if(d.startsWith('0048'))d=d.slice(4);else if(d.startsWith('48')&&d.length===11)d=d.slice(2);d=d.replace(/\D/g,'');if(d.length!==9)throw new Error('Zly PL nr: '+raw);return '+48'+d;}
function detectGender(f){ if(!f) return {salutation:'neutral',a_suffix:''};
 const n=String(f).trim().toLowerCase();
 const MALE_A=new Set(['barnaba','bonawentura','kuba','kosma','sasza','dyzma','jarema','zawisza','juda','aleksa']);
 const MALE_DIM=new Set(['kuba','bartek','staszek','jasiek','wojtek','romek','tomek','olek','antek','franek','maciek','krzysiek','przemek','darek','marek','janek','jurek','zbyszek','rysiek','patryk','dominik','dawidek']);
 const FEMALE_DIM=new Set(['gosia','kasia','basia','zosia','asia','marysia','madzia','karolcia','nikol','miriam','noemi','ester']);
 if(FEMALE_DIM.has(n)) return {salutation:'Pani',a_suffix:'a'};
 if(MALE_DIM.has(n)||MALE_A.has(n)) return {salutation:'Pan',a_suffix:'y'};
 const last=n.slice(-1);
 if(last==='a') return {salutation:'Pani',a_suffix:'a'};
 if(['o','i','y'].includes(last)) return {salutation:'Pan',a_suffix:'y'};
 if(!'aeiouyaeo'.includes(last)) return {salutation:'Pan',a_suffix:'y'};
 return {salutation:'neutral',a_suffix:''}; }
const { DateTime } = require('luxon');
const j = $json.body || $json;
const number = toE164PL(j.phone || j.phoneRaw);
const g = detectGender(j.firstName);
const now = DateTime.now().setZone('Europe/Warsaw');
const inHours = now.weekday <= 5 && now.hour >= 9 && now.hour < 19;
return [{ json: {
  lead_id: j.lead_id || ('L-' + Math.floor(Math.random()*1e6)),
  firstName: j.firstName || '', lastName: j.lastName || '',
  number, branza: j.branza || '',
  salutation: g.salutation === 'neutral' ? '' : g.salutation,
  a_suffix: g.a_suffix,
  allowed: inHours, reason: inHours ? 'ok' : 'poza godzinami 9-19 Pn-Pt'
} }];
